export type Professional={offers?:ProfessionalOffer[];service_packages?:{id:string;name:string;description:string;price_paise:number;duration_minutes:number;included:string[];excluded:string[]}[];contractor_verified?:boolean;id:string;name:string;role:string;city?:string;skills:string[];categories:string[];tools:string[];bio:string;languages:string[];specialties:string[];portrait_url?:string;cover_url?:string;distance_km?:number;outside_preferred_radius?:boolean;rank?:number;rank_category?:string;home_services?:string[];available_now?:boolean;category_records?:{category:string;completed:number;rating:number|null;review_count:number}[];work_history?:{service:string;category:string;completed_at?:number;rating?:number}[];experience_years:number;completed_tasks:number;rating:number|null;review_count:number;distribution:Record<string,number>;reviews:{service:string;rating:number;text:string;at:number;reply?:string}[]};
