 <div className="hire-home-plans" aria-label="Monthly home help"><button onClick={()=>chooseHome('maid')}><img className="hire-home-art" src="/images/cleaning.jpg" alt=""/><span><strong>Maid at home</strong><small>Monthly help · review your plan</small></span><ArrowRight size={16} aria-hidden="true"/></button><button onClick={()=>chooseHome('caretaker')}><img className="hire-home-art" src="/images/family-home-care.jpg" alt=""/><span><strong>Care for your family</strong><small>Non-medical daily assistance</small></span><ArrowRight size={16} aria-hidden="true"/></button></div>
 {!!recentCategories.length&&<section className="hire-recent-categories" aria-label="Categories you explored"><div><Sparkles size={18} aria-hidden="true"/><h2>Continue exploring</h2></div><p>Based on categories you repeatedly explored. Prices stay the same.</p><div>{recentCategories.map(c=><button key={c.id} onClick={()=>chooseCategory(c.id)}>{c.name}<ArrowRight size={14} aria-hidden="true"/></button>)}</div></section>}
