function HireJourney({step}:{step:number}){return <ol className="hire-journey" aria-label="How hiring works">{[['Choose','Find your category'],['Compare','Check scope & budget'],['Agree','Review the quote']].map(([label,detail],index)=><li key={label} aria-current={index+1===step?'step':undefined}><span>{index+1}</span><div><strong>{label}</strong><small>{detail}</small></div></li>)}</ol>;}
